package com.yeyamo_mobile.api.commerce_service.messaging;
import org.springframework.kafka.core.*;import org.springframework.scheduling.annotation.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import java.time.*;import java.util.concurrent.*;
@Component public class OutboxPublisher{private final CommerceOutboxRepository repo;private final KafkaTemplate<String,String>kafka;public OutboxPublisher(CommerceOutboxRepository r,KafkaTemplate<String,String>k){repo=r;kafka=k;}@Scheduled(fixedDelayString="${commerce.outbox.delay-ms:1000}")@Transactional public void publish(){for(var e:repo.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc()){try{kafka.send(e.targetTopic,e.aggregateId,e.payload).get(5,TimeUnit.SECONDS);e.publishedAt=Instant.now();e.lastError=null;}catch(Exception x){e.attempts++;e.lastError=String.valueOf(x.getMessage());}repo.save(e);}}}
